sql_queries.config:
WITH cfg AS (
 SELECT c.*,n.nspname,row_number() OVER (ORDER BY n.nspname,c.cfgname,c.oid) rn
 FROM pg_catalog.pg_ts_config c JOIN pg_catalog.pg_namespace n ON n.oid=c.cfgnamespace
), rec AS (
 SELECT c.rn,c.oid,c.nspname,c.cfgname,pn.nspname||'.'||p.prsname AS parser,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('token',m.maptokentype,'seq',m.mapseqno,'dict',dn.nspname||'.'||d.dictname) ORDER BY m.maptokentype,m.mapseqno)
 FROM pg_catalog.pg_ts_config_map m JOIN pg_catalog.pg_ts_dict d ON d.oid=m.mapdict JOIN pg_catalog.pg_namespace dn ON dn.oid=d.dictnamespace WHERE m.mapcfg=c.oid),'[]'::jsonb) AS maps
 FROM cfg c JOIN pg_catalog.pg_ts_parser p ON p.oid=c.cfgparser JOIN pg_catalog.pg_namespace pn ON pn.oid=p.prsnamespace
)
SELECT rn,oid,nspname,cfgname,parser,maps,md5(nspname||'.'||cfgname||'|'||parser||'|'||maps::text) source_md5 FROM rec ORDER BY rn;
